// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/links", wrapper.GetLinks)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/search", wrapper.Search)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/links/add", wrapper.AddLink)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/links/{identifier}", wrapper.DeleteLink)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/links/{identifier}", wrapper.EditLink)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/links/{identifier}/notes", wrapper.GetLinkNotes)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/links/{identifier}/tags/append", wrapper.AppendTag)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/links/{identifier}/tags/remove", wrapper.RemoveTag)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/links/{identifier}/lists/append", wrapper.AppendList)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/links/{identifier}/lists/remove", wrapper.RemoveList)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/lists", wrapper.GetLists)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/lists", wrapper.CreateList)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/lists/{identifier}", wrapper.DeleteList)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/lists/{identifier}", wrapper.EditList)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/lists/{identifier}/branch", wrapper.DeleteBranch)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/tags", wrapper.GetTags)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/tags", wrapper.CreateTag)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/tags/{identifier}", wrapper.DeleteTag)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/tags/{identifier}", wrapper.EditTag)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/notes", wrapper.AddNote)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/notes/{identifier}", wrapper.DeleteNote)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/notes/{identifier}", wrapper.EditNote)

	return m
}

